/// The client's chart of accounts, whole.
///
/// 7,528 rows lifted verbatim from `Laporan_Master_Account1.csv`: the six rungs
/// of their ladder — 1, 3, 5, 7, 10 and 12 characters — with the twelve-character
/// leaves carrying the unit in their own last two digits.
///
/// # Why the whole file and not a slice
///
/// It used to be a slice: 900 leaves for head office, C004 and C006, on the
/// argument that those were the only accounts the scenarios post to. That was
/// true of a scenario harness and false of a finance application. `Chart of
/// accounts` is a menu now, and a chart of accounts holding an eighth of the
/// accounts is not a chart of accounts — it is a list of the ones we happened
/// to need, and every question asked of it ("do we have an account for X")
/// gets the wrong answer.
///
/// # Why it is packed rather than written out
///
/// 7,528 tuple literals is 400KB of source nobody can read or diff. Tab
/// separated, it is one line per account in the order the client exports them,
/// and a diff against a new export is legible.
///
/// Names are never translated. An accountant looks for "Hutang Affiliasi Atas
/// Barang HEAD OFFICE - C006"; anything else is a different account as far as
/// they are concerned.
///
/// `code \t name \t unit \t active`. Unit is blank above the leaf rung.
